import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useMutation } from 'react-query';
import { useForm } from 'react-hook-form';
import { login, register as registerUser } from '../api/auth';
import { useAuth } from '../contexts/AuthContext';
import { FiMail, FiLock, FiUser, FiEye, FiEyeOff, FiArrowRight } from 'react-icons/fi';
import toast from 'react-hot-toast';

const Auth = () => {
  const navigate = useNavigate();
  const { login: authLogin } = useAuth();
  const [activeTab, setActiveTab] = useState('login');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const {
    register,
    handleSubmit,
    watch,
    formState: { errors },
    reset,
  } = useForm();

  const password = watch('password');

  const loginMutation = useMutation(login, {
    onSuccess: (data) => {
      authLogin(data.user, data.token);
      navigate('/', { replace: true });
      toast.success('Welcome back!');
    },
    onError: (error) => {
      const message = error.response?.data?.message || 'Login failed';
      toast.error(message);
    },
  });

  const registerMutation = useMutation(registerUser, {
    onSuccess: (data) => {
      authLogin(data.user, data.token);
      navigate('/', { replace: true });
      toast.success('Account created successfully!');
    },
    onError: (error) => {
      const message = error.response?.data?.message || 'Registration failed';
      toast.error(message);
    },
  });

  const handleTabChange = (tab) => {
    setActiveTab(tab);
    reset();
  };

  const onLoginSubmit = async (data) => {
    setIsLoading(true);
    try {
      await loginMutation.mutateAsync(data);
    } finally {
      setIsLoading(false);
    }
  };

  const onRegisterSubmit = async (data) => {
    setIsLoading(true);
    try {
      // Remove confirmPassword from the data sent to server
      const { confirmPassword, ...userData } = data;
      await registerMutation.mutateAsync(userData);
    } finally {
      setIsLoading(false);
    }
  };

  const handleGuestLogin = () => {
    toast.info('Guest login feature coming soon!');
  };

  return (
    <div className="auth-split">
      {/* Left: Illustration/Brand */}
      <div className="auth-illustration">
        <img
          src="https://undraw.co/api/illustrations/undraw_chatting_re_j55r.svg"
          alt="Chat Illustration"
          loading="lazy"
        />
        <div className="brand-title">PromptVerse</div>
        <div className="brand-tagline">Unleash your creativity with AI-powered prompts</div>
      </div>
      {/* Right: Auth Form */}
      <div className="auth-form-side">
        <div className="auth-card">
          <h1 className="auth-title">{activeTab === 'login' ? 'Sign In' : 'Create Account'}</h1>
          <div className="auth-tabs">
            <button
              className={`auth-tab ${activeTab === 'login' ? 'active' : ''}`}
              onClick={() => handleTabChange('login')}
            >
              Login
            </button>
            <button
              className={`auth-tab ${activeTab === 'signup' ? 'active' : ''}`}
              onClick={() => handleTabChange('signup')}
            >
              Sign Up
            </button>
          </div>
          {activeTab === 'login' && (
            <form onSubmit={handleSubmit(onLoginSubmit)} className="auth-input-group">
              <div className="auth-input-wrapper">
                <label htmlFor="login-email" className="auth-label">
                  Email Address *
                </label>
                <input
                  id="login-email"
                  type="email"
                  autoComplete="email"
                  {...register('email', {
                    required: 'Email is required',
                    pattern: {
                      value: /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i,
                      message: 'Invalid email address',
                    },
                  })}
                  className={`pl-10 auth-input ${errors.email ? 'border-red-400 focus:border-red-500 focus:ring-red-500' : ''}`}
                  placeholder="guest@example.com"
                />
                <FiMail className="auth-icon" />
                {errors.email && (
                  <p className="auth-error">{errors.email.message}</p>
                )}
              </div>
              <div className="auth-input-wrapper">
                <label htmlFor="login-password" className="auth-label">
                  Password *
                </label>
                <input
                  id="login-password"
                  type={showPassword ? 'text' : 'password'}
                  autoComplete="current-password"
                  {...register('password', {
                    required: 'Password is required',
                    minLength: {
                      value: 6,
                      message: 'Password must be at least 6 characters',
                    },
                  })}
                  className={`pl-10 pr-12 auth-input ${errors.password ? 'border-red-400 focus:border-red-500 focus:ring-red-500' : ''}`}
                  placeholder="Enter your password"
                />
                <FiLock className="auth-icon" />
                <button
                  type="button"
                  className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? (
                    <FiEyeOff className="h-5 w-5" />
                  ) : (
                    <FiEye className="h-5 w-5" />
                  )}
                </button>
                {errors.password && (
                  <p className="auth-error">{errors.password.message}</p>
                )}
              </div>
              <div className="flex items-center justify-between">
                <button
                  type="button"
                  onClick={() => navigate('/forgot-password')}
                  className="text-sm auth-link"
                >
                  Forgot your password?
                </button>
              </div>
              <button
                type="submit"
                disabled={isLoading}
                className="auth-btn-primary"
              >
                {isLoading ? (
                  <div className="auth-loading">
                    <div className="auth-spinner"></div>
                    Signing in...
                  </div>
                ) : (
                  <>
                    Login
                    <FiArrowRight className="w-4 h-4 ml-2" />
                  </>
                )}
              </button>
              <button
                type="button"
                onClick={handleGuestLogin}
                className="auth-btn-secondary"
              >
                Get Guest User Credentials
              </button>
            </form>
          )}
          {activeTab === 'signup' && (
            <form onSubmit={handleSubmit(onRegisterSubmit)} className="auth-input-group">
              <div className="auth-input-wrapper">
                <label htmlFor="signup-username" className="auth-label">
                  Username *
                </label>
                <input
                  id="signup-username"
                  type="text"
                  autoComplete="username"
                  {...register('username', {
                    required: 'Username is required',
                    minLength: {
                      value: 3,
                      message: 'Username must be at least 3 characters',
                    },
                    maxLength: {
                      value: 30,
                      message: 'Username must be less than 30 characters',
                    },
                    pattern: {
                      value: /^[a-zA-Z0-9_]+$/,
                      message: 'Username can only contain letters, numbers, and underscores',
                    },
                  })}
                  className={`pl-10 auth-input ${errors.username ? 'border-red-400 focus:border-red-500 focus:ring-red-500' : ''}`}
                  placeholder="Choose a username"
                />
                <FiUser className="auth-icon" />
                {errors.username && (
                  <p className="auth-error">{errors.username.message}</p>
                )}
              </div>
              <div className="auth-input-wrapper">
                <label htmlFor="signup-email" className="auth-label">
                  Email Address *
                </label>
                <input
                  id="signup-email"
                  type="email"
                  autoComplete="email"
                  {...register('email', {
                    required: 'Email is required',
                    pattern: {
                      value: /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i,
                      message: 'Invalid email address',
                    },
                  })}
                  className={`pl-10 auth-input ${errors.email ? 'border-red-400 focus:border-red-500 focus:ring-red-500' : ''}`}
                  placeholder="Enter your email"
                />
                <FiMail className="auth-icon" />
                {errors.email && (
                  <p className="auth-error">{errors.email.message}</p>
                )}
              </div>
              <div className="auth-input-wrapper">
                <label htmlFor="signup-password" className="auth-label">
                  Password *
                </label>
                <input
                  id="signup-password"
                  type={showPassword ? 'text' : 'password'}
                  autoComplete="new-password"
                  {...register('password', {
                    required: 'Password is required',
                    minLength: {
                      value: 6,
                      message: 'Password must be at least 6 characters',
                    },
                  })}
                  className={`pl-10 pr-12 auth-input ${errors.password ? 'border-red-400 focus:border-red-500 focus:ring-red-500' : ''}`}
                  placeholder="Create a password"
                />
                <FiLock className="auth-icon" />
                <button
                  type="button"
                  className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? (
                    <FiEyeOff className="h-5 w-5" />
                  ) : (
                    <FiEye className="h-5 w-5" />
                  )}
                </button>
                {errors.password && (
                  <p className="auth-error">{errors.password.message}</p>
                )}
              </div>
              <div className="auth-input-wrapper">
                <label htmlFor="signup-confirm-password" className="auth-label">
                  Confirm Password *
                </label>
                <input
                  id="signup-confirm-password"
                  type={showConfirmPassword ? 'text' : 'password'}
                  autoComplete="new-password"
                  {...register('confirmPassword', {
                    required: 'Please confirm your password',
                    validate: (value) =>
                      value === password || 'Passwords do not match',
                  })}
                  className={`pl-10 pr-12 auth-input ${errors.confirmPassword ? 'border-red-400 focus:border-red-500 focus:ring-red-500' : ''}`}
                  placeholder="Confirm your password"
                />
                <FiLock className="auth-icon" />
                <button
                  type="button"
                  className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
                  onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                >
                  {showConfirmPassword ? (
                    <FiEyeOff className="h-5 w-5" />
                  ) : (
                    <FiEye className="h-5 w-5" />
                  )}
                </button>
                {errors.confirmPassword && (
                  <p className="auth-error">{errors.confirmPassword.message}</p>
                )}
              </div>
              <button
                type="submit"
                disabled={isLoading}
                className="auth-btn-primary"
              >
                {isLoading ? (
                  <div className="auth-loading">
                    <div className="auth-spinner"></div>
                    Creating account...
                  </div>
                ) : (
                  'Create account'
                )}
              </button>
            </form>
          )}
        </div>
      </div>
    </div>
  );
};

export default Auth;
